await figma.setCurrentPageAsync(await figma.getNodeByIdAsync('2:5'));
const cfg=CONFIG;
const fonts=new Map();
for(const id of ['219:5719','219:5791','219:5859','5:4551','7:2686','251:6754','269:6783','269:7116','269:7152']){
 const n=await figma.getNodeByIdAsync(id);
 for(const t of n.findAllWithCriteria({types:['TEXT']}))for(const s of t.getStyledTextSegments(['fontName']))fonts.set(JSON.stringify(s.fontName),s.fontName);
}
for(const f of fonts.values())await figma.loadFontAsync(f);
const coll=await figma.variables.getVariableCollectionByIdAsync('VariableCollectionId:2:8');
const vars={};for(const [k,id]of Object.entries({bg:32,surface:33,text:34,muted:35,border:36,s8:45,s12:46,s16:47,s24:48,r12:55}))vars[k]=await figma.variables.getVariableByIdAsync('VariableID:2:'+id);
const created=[],roots={},links=[],mapping={};
function register(n){created.push(n.id,...('findAll'in n?n.findAll(()=>true).map(c=>c.id):[]));}
function paint(n,token,opacity=1){const v=vars[token],c=v.resolveForConsumer(n).value;return figma.variables.setBoundVariableForPaint({type:'SOLID',color:{r:c.r,g:c.g,b:c.b},opacity},'color',v);}
async function freeze(root){
 for(const n of [root,...root.findAll(()=>true)]){
  if('reactions'in n&&n.reactions.length)await n.setReactionsAsync([]);
  if(n.boundVariables?.visible)n.setBoundVariable('visible',null);
  if(n.type==='TEXT'&&n.boundVariables?.characters){const value=n.characters;n.setBoundVariable('characters',null);n.characters=value;}
 }
}
function fit(n){
 if(!('children'in n)||n.type==='COMPONENT')return;
 const inner=n.width-(n.paddingLeft||0)-(n.paddingRight||0);
 for(const c of n.children){
  if(c.layoutPositioning==='ABSOLUTE')continue;
  if((n.layoutMode==='VERTICAL'||n.layoutMode==='HORIZONTAL')&&c.width>inner+1&&inner>0){
   c.resize(inner,c.height);c.layoutSizingHorizontal='FILL';
   if(c.type==='TEXT'){c.textAutoResize='HEIGHT';c.layoutSizingVertical='HUG';}
  }
  if(c.type==='TEXT'&&c.layoutSizingHorizontal==='FILL'){c.textAutoResize='HEIGHT';c.resize(c.width,c.height);c.layoutSizingHorizontal='FILL';c.layoutSizingVertical='HUG';}
  fit(c);
 }
}
async function clone(id,key){
 const source=await figma.getNodeByIdAsync(id),n=source.clone();section.appendChild(n);n.name='Context / '+cfg.label+' / '+key;n.resize(cfg.w,cfg.h);n.layoutSizingHorizontal='FIXED';n.layoutSizingVertical='FIXED';n.setExplicitVariableModeForCollection(coll,cfg.mode);
 await freeze(n);const scroll=n.findOne(c=>c.name==='Settings scroll area');if(scroll){scroll.resize(cfg.w,cfg.h-60);scroll.layoutSizingVertical='FILL';scroll.counterAxisAlignItems='CENTER';const content=scroll.children[0];content.resize(Math.min(cfg.w,848),content.height);content.layoutSizingHorizontal='FIXED';}
 const nav=n.children.find(c=>c.name==='Navigation');if(nav){nav.resize(cfg.w,60);nav.layoutSizingHorizontal='FILL';}
 fit(n);roots[key]=n;return n;
}
const section=figma.createSection();section.name='SECTION_NAME';section.x=cfg.x;section.y=cfg.y;section.resizeWithoutConstraints((cfg.w+80)*3+80,(cfg.h+100)*3+80);created.push(section.id);
