await clone('219:5719','overview');
await clone('219:5791','google');
await clone('219:5859','bcourses');
await clone('7:2686','track');
const bc=roots.bcourses.findOne(c=>c.type==='INSTANCE'&&c.name==='Provider / bCourses');
const longDetails='Courses · 3 selected\n\nHistory 162 — Modern intellectual history: primary sources, seminar discussions and comparative research\nEconomics 101A — Microeconomic analysis and problem-set review\nComputer Science 61A — Structure and interpretation of computer programs\n\nAssignments · Review before Add. New source deadlines need your review.\n\nToken · Managed privately on this Mac. Removing it keeps your courses, cached assignments and tasks. Google can still sync tasks already added from bCourses.';
