const note=roots.bcourses.findOne(c=>c.type==='TEXT'&&c.name==='Local service and offline note');note.characters='Cached assignments remain available offline. Refresh contacts bCourses only when you request it. Saved tasks and the same focus session remain available.';
fit(roots.bcourses);
async function dialog(key,sourceId,backKey){
 const bg=await clone(backKey==='bcourses'?'219:5859':'219:5791',key);
 const scrim=figma.createAutoLayout('VERTICAL');bg.appendChild(scrim);scrim.name='Modal backdrop';scrim.layoutPositioning='ABSOLUTE';scrim.x=0;scrim.y=60;scrim.resize(cfg.w,cfg.h-60);scrim.primaryAxisSizingMode='FIXED';scrim.counterAxisSizingMode='FIXED';scrim.primaryAxisAlignItems='CENTER';scrim.counterAxisAlignItems='CENTER';scrim.fills=[];const veil=figma.createRectangle();bg.insertChild(bg.children.indexOf(scrim),veil);veil.name='Modal dim layer';veil.layoutPositioning='ABSOLUTE';veil.x=0;veil.y=60;veil.resize(cfg.w,cfg.h-60);veil.fills=[paint(veil,'text')];veil.opacity=cfg.mode==='2:2'?.12:.18;scrim.clipsContent=true;
 const d=(await figma.getNodeByIdAsync(sourceId)).clone();scrim.appendChild(d);await freeze(d);d.setExplicitVariableModeForCollection(coll,cfg.mode);d.name='Dialog / '+key;
 const originalChildren=[...d.children];const footer=originalChildren.pop();
 const body=figma.createAutoLayout('VERTICAL');d.insertChild(0,body);body.name='Dialog content scroll area';body.resize(490,10);body.layoutSizingHorizontal='FILL';body.layoutSizingVertical='HUG';body.fills=[];body.clipsContent=true;body.itemSpacing=16;body.setBoundVariable('itemSpacing',vars.s16);
 const content=figma.createAutoLayout('VERTICAL');body.appendChild(content);content.name='Dialog reading content';content.resize(490,10);content.layoutSizingHorizontal='FILL';content.layoutSizingVertical='HUG';content.fills=[];content.itemSpacing=16;content.setBoundVariable('itemSpacing',vars.s16);
 for(const c of originalChildren)content.appendChild(c);
 d.appendChild(footer);footer.name='Persistent dialog actions';
 d.resize(540,d.height);d.layoutSizingVertical='HUG';fit(d);
 const max=cfg.h-120;if(d.height>max){const excess=d.height-max;body.resize(body.width,body.height-excess);body.layoutSizingVertical='FIXED';body.overflowDirection='VERTICAL';d.resize(540,max);d.layoutSizingVertical='FIXED';}
 roots[key]=bg;mapping[key]={dialog:d.id,body:body.id,footer:footer.id,source:sourceId,backKey};
 return bg;
}
