const removed=roots.removed.findOne(c=>c.type==='INSTANCE'&&c.name==='Provider / bCourses');
const removedStatus=removed.findOne(c=>c.type==='TEXT'&&c.name==='Connection status');removedStatus.characters='Token not saved';
const order=['work','overview','google','bcourses','remove','removed','track','consent','offline'];
for(let i=0;i<order.length;i++){const n=roots[order[i]];n.x=80+(i%3)*(cfg.w+80);n.y=80+Math.floor(i/3)*(cfg.h+100);}
async function route(node,target,label){
 if(!node)return; let owner=node;while(owner.parent&&owner.parent.type!=='PAGE'&&owner.parent.type!=='SECTION')owner=owner.parent;if(owner.id===roots[target].id)return;
 const a={type:'NODE',destinationId:roots[target].id,navigation:'NAVIGATE',transition:null,preserveScrollPosition:false};
 await node.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[a]}]);links.push({source:node.id,target:roots[target].id,label});
}
for(const [key,root]of Object.entries(roots)){
 const nav=root.children.find(c=>c.name==='Navigation');
 for(const b of nav?.children??[]){
  if(b.name.includes('Settings'))await route(b,key==='work'||key==='track'?'overview':'work','Settings/close');
  if(b.name==='Action / Plan')await route(b,'work','Plan');
  if(b.name==='Action / Track')await route(b,'track','Track');
 }
 await route(root.findOne(c=>c.name==='Action / Back to work'),'work','Back to work');
 await route(root.findOne(c=>c.name==='Action / Open timer'),'track','Open same timer sample');
 if(key==='overview'||key==='google'||key==='bcourses'){
  const b=root.findOne(c=>c.type==='INSTANCE'&&c.name==='Provider / bCourses'),g=root.findOne(c=>c.type==='INSTANCE'&&c.name==='Provider / Google');
  await route(b?.findOne(c=>c.type==='INSTANCE'&&/Manage|Hide/.test(c.name)),'bcourses','Manage bCourses');
  await route(g?.findOne(c=>c.type==='INSTANCE'&&/Manage|Hide/.test(c.name)),'google','Manage Google');
  if(key==='google'){
   await route(g.findOne(c=>c.name==='Action / Sign-in & calendars'),'consent','Google scope sample');

  }
  if(key==='bcourses')await route(b.findOne(c=>c.name==='Action / Remove bCourses token'),'remove','Review removal');
 }
 if(mapping[key]){
  const d=await figma.getNodeByIdAsync(mapping[key].dialog);
  for(const b of d.findAllWithCriteria({types:['INSTANCE']})){
   const label=b.findAllWithCriteria({types:['TEXT']}).map(t=>t.characters).join(' ');
   if(['Not now','Close','Keep token','Keep connection'].includes(label))await route(b,mapping[key].backKey,label);
   if(label==='Back to work')await route(b,'work',label);
   if(key==='remove'&&label==='Remove token')await route(b,'removed','Simulate local removal receipt');
  }
 }
}
for(const root of Object.values(roots))register(root);
return {createdNodeIds:[...new Set(created)],mutatedNodeIds:[],section:{id:section.id,name:section.name,x:section.x,y:section.y,width:section.width,height:section.height},config:cfg,frames:Object.fromEntries(Object.entries(roots).map(([k,n])=>[k,{id:n.id,width:n.width,height:n.height}])),dialogs:mapping,links};

